timeout 60 bash -c "until kubectl -n '${Q14_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl label node "${Q14_PLACE_NODE}" disk="${Q14_PLACE_DISK}" --overwrite
